// FCM behind a small interface, so the rest of the app (and its tests) never touch Firebase.
// Push is on only on Android, iOS and the web, and only once Firebase is configured
// (lib/push/firebase_options.dart generated by scripts/setup-firebase.sh).
import 'dart:async';

import 'package:firebase_core/firebase_core.dart';
import 'package:firebase_messaging/firebase_messaging.dart';
import 'package:flutter/foundation.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import 'firebase_options.dart';

/// What a push carried: the visible text and the chat it's about (null for a test push).
class PushMessage {
  const PushMessage({this.chatId, this.title, this.body});

  final String? chatId;
  final String? title;
  final String? body;

  factory PushMessage.fromData(Map<String, Object?> data, {String? title, String? body}) =>
      PushMessage(chatId: data['chatId'] is String ? data['chatId'] as String : null, title: title, body: body);
}

abstract class PushMessaging {
  /// Asks the OS (or browser) to allow notifications; true when allowed.
  Future<bool> requestPermission();

  /// Whether notifications are already allowed, without asking.
  Future<bool> permissionGranted();

  /// This install's FCM token, or null when there is none yet.
  Future<String?> getToken();

  Stream<String> get onTokenRefresh;

  /// Pushes that arrive while the app is in the foreground (the OS shows nothing then).
  Stream<PushMessage> get onMessage;

  /// Taps on a notification while the app was running in the background.
  Stream<PushMessage> get onMessageOpenedApp;

  /// The notification tap that launched the app, once.
  Future<PushMessage?> getInitialMessage();
}

/// The platforms FCM serves here. Desktop apps notify from their socket instead.
bool isPushPlatform({bool web = kIsWeb, TargetPlatform? platform}) {
  if (web) return true;
  final p = platform ?? defaultTargetPlatform;
  return p == TargetPlatform.android || p == TargetPlatform.iOS;
}

/// The Firebase options for this platform, or null while Firebase isn't configured.
FirebaseOptions? firebaseOptions([FirebaseOptions Function()? read]) {
  try {
    return (read ?? () => DefaultFirebaseOptions.currentPlatform)();
  } on UnsupportedError {
    return null;
  }
}

/// Starts Firebase and returns FCM, or null when push is off here. Never throws.
Future<PushMessaging?> initPush({
  bool? pushPlatform,
  FirebaseOptions? Function()? options,
  Future<void> Function(FirebaseOptions)? initialize,
}) async {
  if (!(pushPlatform ?? isPushPlatform())) return null;
  final o = (options ?? firebaseOptions)();
  if (o == null) return null;
  try {
    await (initialize ?? (o) => Firebase.initializeApp(options: o)).call(o).timeout(const Duration(seconds: 10));
    return FirebasePushMessaging();
  } catch (e) {
    debugPrint('push off: Firebase failed to start: $e');
    return null;
  }
}

/// FCM, or null when push is off on this device. main() overrides it after [initPush].
final pushMessagingProvider = Provider<PushMessaging?>((ref) => null);

class FirebasePushMessaging implements PushMessaging {
  FirebaseMessaging get _m => FirebaseMessaging.instance;

  static bool _allowed(NotificationSettings s) =>
      s.authorizationStatus == AuthorizationStatus.authorized ||
      s.authorizationStatus == AuthorizationStatus.provisional;

  static PushMessage _from(RemoteMessage m) =>
      PushMessage.fromData(m.data, title: m.notification?.title, body: m.notification?.body);

  @override
  Future<bool> requestPermission() async => _allowed(await _m.requestPermission());

  @override
  Future<bool> permissionGranted() async => _allowed(await _m.getNotificationSettings());

  @override
  Future<String?> getToken() async {
    if (!kIsWeb && defaultTargetPlatform == TargetPlatform.iOS) {
      // FCM needs the APNs token first, which arrives shortly after permission is granted.
      for (var i = 0; i < 10 && await _m.getAPNSToken() == null; i++) {
        await Future<void>.delayed(const Duration(seconds: 1));
      }
    }
    // The classic FCM registration token, which FCM HTTP v1 sends to (the server's `token` target);
    // the newer FID registration API isn't used. On the web this uses Firebase's default VAPID key.
    // ignore: deprecated_member_use
    return _m.getToken();
  }

  @override
  // ignore: deprecated_member_use
  Stream<String> get onTokenRefresh => _m.onTokenRefresh;

  @override
  Stream<PushMessage> get onMessage => FirebaseMessaging.onMessage.map(_from);

  @override
  Stream<PushMessage> get onMessageOpenedApp => FirebaseMessaging.onMessageOpenedApp.map(_from);

  @override
  Future<PushMessage?> getInitialMessage() async {
    final m = await _m.getInitialMessage();
    return m == null ? null : _from(m);
  }
}
